export function SplitPreview({
  editorContent = "{{editorContent}}",
  layout = "{{layout}}",
  accent = "{{accent}}",
  syncScroll = {{syncScroll}},
  splitRatio = {{splitRatio}},
}) {
  const stacked = layout === "stacked";
  return (
    <div style={{ display: "flex", flexDirection: stacked ? "column" : "row", fontFamily: "system-ui, sans-serif", color: "#241430", background: "#FAF7F2", border: "1.5px solid #24143020", borderRadius: 10, overflow: "hidden", maxWidth: 460 }}>
      <div style={{ padding: "14px 16px", minWidth: 0, flexBasis: stacked ? "auto" : `${splitRatio}%` }}>
        <p style={{ margin: "0 0 6px", fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".04em", color: "#241430aa" }}>Editor</p>
        <div contentEditable suppressContentEditableWarning role="textbox" aria-multiline="true" aria-label="Source content" style={{ fontFamily: "ui-monospace, monospace", fontSize: 13, whiteSpace: "pre-wrap" }}>{editorContent}</div>
      </div>
      <div aria-hidden="true" style={{ width: stacked ? "auto" : 1.5, height: stacked ? 1.5 : "auto", background: "#24143020", display: "flex", alignItems: "center", justifyContent: "center", position: "relative" }}>
        <span title={syncScroll ? "Scroll synced" : "Scroll not synced"} style={{ position: "absolute", fontSize: 13, background: "#FAF7F2", color: syncScroll ? accent : "#24143040" }}>{"\u21C5"}</span>
      </div>
      <div style={{ padding: "14px 16px", minWidth: 0, flex: 1 }}>
        <p style={{ margin: "0 0 6px", fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".04em", color: "#241430aa" }}>Preview</p>
        <div style={{ fontSize: 15, lineHeight: 1.6 }}>{editorContent}</div>
      </div>
    </div>
  );
}
